args.code:
H_TARGET = -4.0
K = 2.5

def control(obs):
    st = obs.get('status')
    h = obs.get('hitch_deg', 0.0) or 0.0
    rem = obs.get('progress', {}).get('remaining', 30.0)
    if st in ('JACKKNIFED', 'PINNED'):
        return (0.0, 1.0, -23)
    if rem is not None and rem < 0.5:
        return (0.0, 0.0, -23)
    err = h - H_TARGET
    steer = max(-30.0, min(30.0, K * err))
    return (steer, -0.8, -23)

