args.code:
PH = 'fwd'
T0 = None

def control(obs):
    global PH, T0
    st = obs.get('status')
    t = obs.get('t', 0.0) or 0.0
    h = obs.get('hitch_deg', 0.0) or 0.0
    v = (obs.get('motion') or {}).get('v_mps', 0.0) or 0.0
    rem = (obs.get('progress') or {}).get('remaining', 30.0)
    if rem is not None and rem < 0.5:
        return (0.0, 0.0, -23)
    if PH == 'rev' and st in ('JACKKNIFED', 'PINNED'):
        PH = 'fwd'
        T0 = None
    if PH == 'fwd':
        if v > 0.1 and T0 is None:
            T0 = t
        if T0 is not None and ((t - T0 > 2.0 and abs(h) < 2.5) or (t - T0 > 6.0)):
            PH = 'rev'
        else:
            return (0.0, 0.8, -23)
    steer = max(-30.0, min(30.0, 2.5 * h))
    return (steer, -0.8, -23)

