    if _st['mode'] == 'rev' and (s in ('JACKKNIFED', 'PINNED') or abs(h) > 40.0):
        _st['mode'] = 'fwd'
        _st['t0'] = t
    if _st['mode'] == 'fwd':
        if t - _st['t0'] < 2.5:
            return (0.0, 1.0)
        _st['mode'] = 'rev'
    steer = max(-45.0, min(45.0, 1.2 * h))
    return (steer, -1.0)

