    s = obs.get('status', 'READY')
    rear = obs.get('rig', {}).get('trailer_rear', [0.0, 0.0])
    y = float(rear[1])
    if _st['mode'] == 'rev' and (s in ('JACKKNIFED', 'PINNED') or abs(h) > 35.0):
        _st['mode'] = 'fwd'
        _st['t0'] = t
    if _st['mode'] == 'fwd':
        if t - _st['t0'] < 3.0:
            return (0.0, 0.8, 180)
        _st['mode'] = 'rev'
    steer = 1.2 * h + 3.0 * (y + 0.4)
    steer = max(-45.0, min(45.0, steer))
    return (steer, -0.4, 180)

