_s = {'phase': 'fwd', 't0': None, 'prev': None}

def control(obs):
    t = float(obs.get('t', 0.0))
    dt = float(obs.get('dt', 0.1) or 0.1)
    h = float(obs.get('hitch_deg', 0.0))
    st = obs.get('status', 'READY')
    if _s['t0'] is None:
        _s['t0'] = t
    if _s['phase'] == 'fwd':
        if t - _s['t0'] >= 3.0:
            _s['phase'] = 'rev'
            _s['t0'] = t
            _s['prev'] = None
        else:
            return {'steer_deg': 0.0, 'speed_mps': 0.4, 'look_deg': 180.0}
    # reverse phase
    if st in ('JACKKNIFED', 'PINNED') or abs(h) > 25.0:
        _s['phase'] = 'fwd'
        _s['t0'] = t
        return {'steer_deg': 0.0, 'speed_mps': 0.4, 'look_deg': 180.0}
    p = _s['prev']
    rate = 0.0 if p is None else (h - p) / dt
    _s['prev'] = h
    steer = 2.0 * h + 0.15 * rate
    steer = max(-30.0, min(30.0, steer))
    speed = -0.4 if abs(h) < 10.0 else -0.25
    return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': 180.0}

